// RegisterMessagesServer registers the MessagesServer server with the TLRPC server.
func RegisterMessagesServer(s *tlrpc.Server, srv MessagesServer) {
	// If the following call panics, it indicates UnimplementedMessagesServer was
	// embedded by pointer and is nil. This will cause panics if an
	// unimplemented method is ever invoked, so we test this at initialization
	// time to prevent it from happening at runtime later due to I/O.
	if t, ok := srv.(interface{ testEmbeddedByValue() }); ok {
		t.testEmbeddedByValue()
	}
	s.RegisterService(Messages_ServiceDesc, srv)
}

