// RegisterPaymentsServer registers the PaymentsServer server with the TLRPC server.
func RegisterPaymentsServer(s *tlrpc.Server, srv PaymentsServer) {
	// If the following call panics, it indicates UnimplementedPaymentsServer was
	// embedded by pointer and is nil. This will cause panics if an
	// unimplemented method is ever invoked, so we test this at initialization
	// time to prevent it from happening at runtime later due to I/O.
	if t, ok := srv.(interface{ testEmbeddedByValue() }); ok {
		t.testEmbeddedByValue()
	}
	s.RegisterService(Payments_ServiceDesc, srv)
}

